    [1251693] = { en = "Damage and healing done by magical spells and effects increased by $w1% for $d from cooling off from the sun.", description = "Danni e cure inflitti da incantesimi ed effetti magici aumentati del $w1% per $d grazie al riparo dal sole." },
    [1251986] = { en = "Whenever you suffer Bleed damage, one dose is splashed to a nearby enemy within $s~2 yds.\r\n\r\nWhen this effect expires, you will suffer $w1 Nature damage.", description = "Ogni volta che subisci danni da Sanguinamento, una dose schizza su un nemico vicino entro $s~2 m.\r\n\r\nQuando questo effetto termina, subirai $w1 danni della Natura." },
    [1251993] = { en = "A nearby bleeding target has splashed Venomous Blood onto you.\r\n\r\nWhen this effect expires, you will suffer $w1 Nature damage.", description = "Un bersaglio sanguinante nelle vicinanze ti ha schizzato addosso Sangue Velenoso.\r\n\r\nQuando questo effetto termina, subirai $w1 danni della Natura." },
    [1252546] = { en = "Chance to hit with attacks reduced by $w1%.", description = "Probabilità di colpire con gli attacchi ridotta del $w1%." },
    [1252559] = { en = "Attack Power increased by $w1 against Beasts.", description = "Potenza d'attacco aumentata di $w1 contro le Bestie." },
    [1253348] = { en = "You smell like garbage. Everything around you probably hates the smell.", description = "Puzzi di spazzatura. Probabilmente tutto ciò che ti circonda detesta l'odore." },
