    [1262528] = { en = "Rathiril has cast a spell on you, allowing you to walk on water for a short time.", description = "Rathiril ti ha lanciato un incantesimo che ti permette di camminare sull'acqua per un breve periodo." },
    [1262542] = { en = "|cnPURE_RED_COLOR:Notice from Management:\r\n|cnITEM_STANDARD_COLOR:\r\nIncase you forgot, this place is from the second war and is in NO SHAPE to be retrofitted to accommodate the more \"husky\" contributors to our alliance. Until further notice, all visitors will be magically improved to ensure they STOP BUMPING INTO THINGS!\r\n\r\n|cnIQ2:Size corrected.", description = "|cnPURE_RED_COLOR:Avviso della Direzione:\r\n|cnITEM_STANDARD_COLOR:\r\nNel caso te ne fossi dimenticato, questo luogo risale alla Seconda Guerra e NON È ASSOLUTAMENTE ADATTO a essere ristrutturato per accogliere i contributori più \"robusti\" della nostra alleanza. Fino a nuovo avviso, tutti i visitatori saranno magicamente migliorati per assicurarsi che SMETTANO DI SBATTERE CONTRO LE COSE!\r\n\r\n|cnIQ2:Taglia corretta." },
    [1262943] = { en = "Fleeing in fear from watching its fellow flowers get trampled!", description = "Fugge terrorizzato dopo aver visto i suoi fiori compagni venire calpestati!" },
    [1263086] = { en = "Healing received reduced by $S1% for $d1.", description = "Cure ricevute ridotte del $S1% per $d1." },
