    [1269555] = { en = "Your soul is beginning to fracture. After $d you are stunned for $1269557d and create a Fragmented Soul", description = "La tua anima sta iniziando a fratturarsi. Dopo $d rimani stordito per $1269557d e crei un'Anima frammentata" },
