    [1269955] = { en = "Shadow damage done and taken increased by $w1% during the fel-touched ash. You should find a way to cleanse yourself.", description = "Danni da ombra inflitti e subiti aumentati del $w1% durante la cenere corrotta. Dovresti trovare un modo per purificarti." },
    [1269962] = { en = "Damage and healing done by magical spells and effects increased by $w1% in the intense sunlight. You should cool off.", description = "Danni e cure inflitti da incantesimi ed effetti magici aumentati del $w1% sotto la luce solare intensa. Dovresti rinfrescarti." },
