    [1271351] = { en = "$s1 Arcane damage inflicted every $t1 sec.\r\n\r\nUpon removal, a collapsing star forms. Enemies within the star suffer $1271414s2 Arcane damage every $1271414t2 sec and have their movement speed reduced by $1271414s1%.", description = "Infligge $s1 danni arcani ogni $t1 s.\r\n\r\nAlla rimozione, si forma una stella in collasso. I nemici al suo interno subiscono $1271414s2 danni arcani ogni $1271414t2 s e la loro velocità di movimento è ridotta del $1271414s1%." },
