    [1271414] = { en = "Movement speed reduced by $s1%.\r\n$s2 Arcane damage inflicted every $t2 sec.", description = "Velocità di movimento ridotta del $s1%.\r\nInfligge $s2 danni arcani ogni $t2 s." },
